window.POSTS=[{"t":"n","date":"13 ต.ค. 2569","title":"จากห้องเรียนสี่เหลี่ยม สู่ผืนนาไร้ขอบเขต","body":"จากห้องเรียนสี่เหลี่ยม สู่ผืนนาไร้ขอบเขต   \n.\nท่ามกลางกระแสที่ทุกคนต้องหันไปพึ่งวิธีทำนาที่เร็ว และง่ายขึ้นเพื่อความอยู่รอด กลุ่มสำนึกรักบ้านเกิดจังหวัดศรีสะเกษก ลับเลือกทำสิ่งที่สวนทาง พวกเขากันพื้นที่นาผืนเล็ก ๆ ท้ายหมู่บ้านเอาไว้เพื่อ \"ปักดำ\" แบบโบราณโดยเฉพาะ ไม่ใช่เพื่อหวังผลผลิตสูงสุด แต่เพื่อให้เด็ก ๆ ได้สัมผัสวิถีที่บรรพบุรุษเคยทำมา\n\nนี่คือ บ้านตาจวน ตำบลสำโรงพลัน อำเภอไพรบึง จังหวัดศรีสะเกษ หมู่บ้านเล็ก ๆ ที่ตั้งอยู่ริมถนนสาย 24 โชคชัย-เดชอุดม และมีความพิเศษที่หาไม่ได้จากที่ไหนในตำบล เพราะขณะที่หมู่บ้านรอบข้างสื่อสารกันด้วยภาษาเขมรเป็นหลัก ที่นี่คือหนึ่งเดียวที่ยังพูดภาษาถิ่น \"กวย\" กันในชีวิตประจำวัน และวันนี้ ภาษา วิถี และรากเหง้าของบรรพบุรุษกวย กำลังถูกส่งต่อผ่านโคลนเลนใต้ฝ่าเท้าของเด็ก ๆ\nhttps://www.thaipbs.or.th/locals/contents/dehahqd0gwvmsui9db1zu52r-ซนาบในมือเด็ก-เมื่อโคลนกลายเป็นห้องเรียนที่บ้านตาจวน\n\nขอบคุณภาพและเรื่องราว : ขวัญชิต โพธิ์กระสังข์\n\nhttps://www.thaipbs.or.th/locals/contents/dehahqd0gwvmsui9db1zu52r-%E0%B8%8B%E0%B8%99%E0%B8%B2%E0%B8%9A%E0%B9%83%E0%B8%99%E0%B8%A1%E0%B8%B7%E0%B8%AD%E0%B9%80%E0%B8%94%E0%B9%87%E0%B8%81-%E0%B9%80%E0%B8%A1%E0%B8%B7%E0%B9%88%E0%B8%AD%E0%B9%82%E0%B8%84%E0%B8%A5%E0%B8%99%E0%B8%81%E0%B8%A5%E0%B8%B2%E0%B8%A2%E0%B9%80%E0%B8%9B%E0%B9%87%E0%B8%99%E0%B8%AB%E0%B9%89%E0%B8%AD%E0%B8%87%E0%B9%80%E0%B8%A3%E0%B8%B5%E0%B8%A2%E0%B8%99%E0%B8%97%E0%B8%B5%E0%B9%88%E0%B8%9A%E0%B9%89%E0%B8%B2%E0%B8%99%E0%B8%95%E0%B8%B2%E0%B8%88%E0%B8%A7%E0%B8%99","photos":[{"src":"data:image/jpeg;base64,","cap":""}],"link":{"url":"https://www.thaipbs.or.th/locals/contents/dehahqd0gwvmsui9db1zu52r-%E0%B8%8B%E0%B8%99%E0%B8%B2%E0%B8%9A%E0%B9%83%E0%B8%99%E0%B8%A1%E0%B8%B7%E0%B8%AD%E0%B9%80%E0%B8%94%E0%B9%87%E0%B8%81-%E0%B9%80%E0%B8%A1%E0%B8%B7%E0%B9%88%E0%B8%AD%E0%B9%82%E0%B8%84%E0%B8%A5%E0%B8%99%E0%B8%81%E0%B8%A5%E0%B8%B2%E0%B8%A2%E0%B9%80%E0%B8%9B%E0%B9%87%E0%B8%99%E0%B8%AB%E0%B9%89%E0%B8%AD%E0%B8%87%E0%B9%80%E0%B8%A3%E0%B8%B5%E0%B8%A2%E0%B8%99%E0%B8%97%E0%B8%B5%E0%B9%88%E0%B8%9A%E0%B9%89%E0%B8%B2%E0%B8%99%E0%B8%95%E0%B8%B2%E0%B8%88%E0%B8%A7%E0%B8%99"},"pin":"14.972700,102.099300","by":"konkuay","byId":"amv6bn9nx6gl7","id":"pmv6d0hkas408"},{"t":"s","date":"13 ต.ค. 2569","title":"เทะ ตะแวลย์: ของว่างภูมิปัญญาชาวกวย แซ่บถึงใจตามฤดูกาล","body":"“เยอ แซมซาย จาเทะตะแวลย์”\nสวัสดีพี่น้องและเพื่อน ๆ ทุกคนครับ วันนี้ขอพามาเปิดสำรับของว่างพื้นบ้านแบบฉบับชาวกวยบ้านเรากันสักหน่อย นี่คือ “เทะ ตะแวลย์” ที่รวบรวมพืชผักและผลไม้ตามฤดูกาลสด ๆ จากธรรมชาติ มาทานคู่กับพริกสมุนไพรตำรสเด็ดสูตรพื้นบ้าน\nในภาพจะเห็นกิ่งผลไม้ป่าลูกเล็กเป็นช่อ ใบไม้เขียวเข้มผืนใหญ่ มะนาว เครื่องเปรี้ยว และถ้วยพริกสมุนไพรที่ตำจนเข้ากัน วางรวมกันบนถาดเดียว ใครอยากหยิบอะไรก็หยิบ นั่งล้อมวงกินไปคุยไปได้ทั้งบ่าย\nความเปรี้ยว ความมัน และความกรุบกรอบของผลไม้ป่าผสมผสานกับใบไม้สมุนไพร พอจิ้มกับพริกสมุนไพรแซ่บ ๆ บอกเลยว่าคำเดียวไม่เคยพอ กินเพลินจนวางมือไม่ลงเลยทีเดียว\nสิ่งที่น่าสนใจคือ สำรับนี้ไม่ได้เป็นแค่ของกินเล่น แต่เป็นความรู้ของคนรุ่นก่อนว่า ฤดูไหนมีอะไรออกผล เก็บจากไหน กินคู่กับอะไรถึงลงตัว และต้องปรุงรสพริกอย่างไร ความรู้เหล่านี้ไม่มีในตำรา แต่ส่งต่อกันด้วยการนั่งกินและลงมือทำด้วยกัน\nคำแนะนำเล็ก ๆ: ผลไม้ป่าและใบไม้บางชนิดหน้าตาคล้ายกัน ก่อนเก็บมาลองกิน ควรถามผู้เฒ่าหรือผู้รู้ในหมู่บ้านให้แน่ใจก่อนว่าชนิดไหนกินได้\nตัวอย่าง: ใส่ชื่อพืชแต่ละชนิดในภาษากวยและภาษาไทย ฤดูกาลที่ออกผล และส่วนผสมของพริกสมุนไพรตามที่ผู้เฒ่าบอก\nตัวอย่าง: ใครรู้ความหมายของประโยค “เยอ แซมซาย จาเทะตะแวลย์” และคำว่า “เทะ ตะแวลย์” ในภาษากวย ช่วยบอกทีมงานเพื่อใส่ไว้ตรงนี้\nบ้านใครมีเมนูของว่างแนวนี้ หรือมีเคล็ดลับที่ทำให้ “เทะ ตะแวลย์” จานนี้อร่อยเด็ดสะระตี่ขึ้นไปอีก ลองมาแชร์กันหน่อยครับ ต้องใส่อะไรเพิ่ม หรือมีสูตรพริกจิ้มแบบไหนถึงจะนัวสุด ๆ ส่งมาที่ทีมงานได้เลย มาคุยกันหน่อยเร้ว!","photos":[{"src":"data:image/jpeg;base64,","cap":""},{"src":"data:image/jpeg;base64,","cap":""},{"src":"data:image/jpeg;base64,","cap":""},{"src":"data:image/jpeg;base64,","cap":""}],"link":{"url":""},"pin":"บ้านตาจวน ไพรบึง ศรีสะเกษ","orig":"เทะ ตะแวลย์: ของว่างภูมิปัญญาชาวกวย แซ่บถึงใจตามฤดูกาล","id":"pmv6bp304w6f9"},{"t":"n","date":"13 ต.ค. 2569","title":"ประชาสัมพันธ์: ถนน คสล. เส้นตาจวน–โคกพยอม รถหนัก/รถใหญ่ผ่านไม่ได้","body":"ถนน คสล. เส้นตาจวน–โคกพยอม รถหนักและรถใหญ่ไม่สามารถผ่านได้\nบริเวณด้านล่างท่อระบายน้ำมีน้ำเซาะดินออกหมดแล้ว ขอให้ใช้การสัญจรจากเส้นอื่นแทนไปก่อน\nรถทั่วไปที่จำเป็นต้องใช้เส้นทางนี้ โปรดใช้รถใช้ถนนด้วยความระมัดระวัง\nขออภัยในความไม่สะดวก","photos":[{"src":"img/road-pipe-1.jpg","cap":"ท่อระบายน้ำริมถนน น้ำเซาะดินรอบท่อ"},{"src":"img/road-pipe-2.jpg","cap":"ท่อระบายน้ำใต้ถนน ดินใต้ถนนถูกเซาะ"},{"src":"img/road-pipe-3.jpg","cap":"ใต้พื้นถนน มีช่องว่างและดินพังลงมา"}],"link":{"url":""},"pin":"ถนน ตาจวน โคกพยอม ไพรบึง ศรีสะเกษ","orig":"ประชาสัมพันธ์: ถนน คสล. เส้นตาจวน–โคกพยอม รถหนัก/รถใหญ่ผ่านไม่ได้"}];